/*
 * Symbol isolation rules for the ST-only libscatter_aicpu_kernel.so.
 *
 * ST relies on global weak-symbol interposition provided by hccl_stub.cc,
 * so symbols remain globally visible by default.
 *
 * The C++ interfaces below are localized to prevent them from binding to
 * the implementations exported by libhccl.so.
 */
{
    global:
        *;

    local:
        extern "C++" {
            "ops_hccl::ExecuteSelector::ExecuteSelector()";
            "ops_hccl::ExecuteSelector::Run(ops_hccl::OpParam&, ops_hccl::TopoInfoWithNetLayerDetails*, std::string&) const";

            "ops_hccl::CollAlgExecRegistryV2::Instance()";
            "ops_hccl::CollAlgExecRegistryV2::GetAlgExec(HcclCMDType, std::string const&)";

            "ops_hccl::HcclGetAlgRes(void*, ops_hccl::OpParam&, std::unique_ptr<ops_hccl::InsCollAlgBase, std::default_delete<ops_hccl::InsCollAlgBase> >&, ops_hccl::TopoInfoWithNetLayerDetails*, std::unique_ptr<ops_hccl::AlgResourceCtxSerializable, std::default_delete<ops_hccl::AlgResourceCtxSerializable> >&, void**, bool&, ops_hccl::ResPackGraphMode const&)";
        };
};